contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _am) public payable {
        require(true);

        uint256 beforeBalanceC = address(c).balance;
        uint256 beforeUser = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterUser = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterBalanceC = address(c).balance;

        assert(_am <= beforeUser || (afterUser == beforeUser && afterBalanceC == beforeBalanceC));
    }

    receive() external payable {}
}

